791	fn draw_input_bar(stdout: &mut impl Write, prefix: &str, value: &str, w: usize, h: usize) -> io::Result<()> {
792	    let prefix_len = prefix.chars().count();
793	    let text: String = value.chars().take(w.saturating_sub(prefix_len + 2)).collect();
794	    let content = format!("{prefix}{text}");
795	    let padded = format!("{:<width$}", content, width = w);
796	    execute!(stdout, cursor::MoveTo(0, (h - 1) as u16))?;
797	    write!(stdout, "\x1b[7m{padded}\x1b[0m")?;
798	    let col = (prefix_len + text.chars().count()).min(w.saturating_sub(1)) as u16;
799	    execute!(stdout, cursor::MoveTo(col, (h - 1) as u16))?;
800	    stdout.flush()
801	}
802	
803	fn collect_search_query(stdout: &mut impl Write, w: usize, h: usize) -> Option<String> {
804	    collect_text_input(stdout, "  / ", w, h)
805	}
