807	// ── New session wizard ────────────────────────────────────────────────────────
808	
809	/// A 4-step panel drawn over the bottom of the screen. Each completed step
810	/// stays visible with its confirmed value while the user fills the next one.
811	fn new_session_wizard(stdout: &mut impl Write, repo_dir: &str, w: usize, h: usize) -> Option<NewSessionConfig> {
812	    const LABEL_W: usize = 24;
813	    // Panel rows: title, blank, agent, branch, name, prompt, blank  (7 rows + 1 status bar)
814	    const PANEL_H: usize = 7;
815	
816	    let t = crate::theme::get();
817	    let panel_top = h.saturating_sub(PANEL_H + 1);
818	
819	    let mut step = 0usize;           // 0=agent 1=branch 2=name 3=prompt
820	    let mut agent_sel = 0usize;
821	    let mut confirmed_agent = 0usize;
822	    let mut inputs = [String::new(), String::new(), String::new()]; // branch, name, prompt
823	
824	    execute!(stdout, cursor::Show).ok();
825	
826	    loop {
827	        // ── Draw panel ────────────────────────────────────────────────────────
828	        // Title row
829	        execute!(stdout, cursor::MoveTo(0, panel_top as u16)).ok();
830	        write!(stdout, "\x1b[{hd}m  New Session\x1b[0m", hd = t.header).ok();
831	        execute!(stdout, terminal::Clear(ClearType::UntilNewLine)).ok();
832	
833	        // Blank separator
834	        execute!(stdout, cursor::MoveTo(0, (panel_top + 1) as u16)).ok();
835	        execute!(stdout, terminal::Clear(ClearType::UntilNewLine)).ok();
836	
837	        let step_rows  = [panel_top + 2, panel_top + 3, panel_top + 4, panel_top + 5];
838	        let step_labels = ["  Agent", "  Worktree branch", "  Session name", "  Prompt"];
839	
840	        for (i, (&row, &label)) in step_rows.iter().zip(step_labels.iter()).enumerate() {
841	            execute!(stdout, cursor::MoveTo(0, row as u16)).ok();
842	            let lpart = format!("{label:<LABEL_W$}");
843	
844	            if i < step {
845	                // Completed — dim label, value in colour
846	                let val = if i == 0 {
847	                    let (name, _, col) = AGENTS[confirmed_agent];
848	                    format!("\x1b[38;5;{col}m{name}\x1b[0m")
849	                } else {
850	                    let v = inputs[i - 1].trim();
851	                    if v.is_empty() { format!("\x1b[{ft}m(skip)\x1b[0m", ft = t.text_faint) }
852	                    else            { format!("\x1b[{pm}m{v}\x1b[0m", pm = t.text_primary) }
853	                };
854	                write!(stdout, "\x1b[{dm}m{lpart}\x1b[0m{val}", dm = t.text_dim).ok();
855	            } else if i == step {
856	                // Active step
857	                write!(stdout, "\x1b[{pm}m{lpart}\x1b[0m", pm = t.text_primary).ok();
858	                if i == 0 {
859	                    // Inline agent picker
860	                    for (ai, (name, _, col)) in AGENTS.iter().enumerate() {
861	                        if ai > 0 { write!(stdout, "\x1b[{ft}m │ \x1b[0m", ft = t.text_faint).ok(); }
862	                        if ai == agent_sel {
863	                            write!(stdout, "\x1b[{sb};38;5;{col}m {name} \x1b[0m", sb = t.sel_bg).ok();
864	                        } else {
865	                            write!(stdout, "\x1b[{dm}m {name}\x1b[0m", dm = t.text_dim).ok();
866	                        }
867	                    }
868	                } else {
869	                    // Text input — print typed chars, terminal cursor sits here
870	                    write!(stdout, "\x1b[{pm}m{}\x1b[0m", inputs[i - 1], pm = t.text_primary).ok();
871	                }
872	            } else {
873	                // Future step — very dim label only
874	                write!(stdout, "\x1b[{ft}m{lpart}\x1b[0m", ft = t.text_faint).ok();
875	            }
876	            execute!(stdout, terminal::Clear(ClearType::UntilNewLine)).ok();
877	        }
878	
879	        // Trailing blank row
880	        let blank2 = panel_top + 6;
881	        if blank2 < h.saturating_sub(1) {
882	            execute!(stdout, cursor::MoveTo(0, blank2 as u16)).ok();
883	            execute!(stdout, terminal::Clear(ClearType::UntilNewLine)).ok();
884	        }
885	
886	        // Status bar hint
887	        let bar = if step == 0 {
888	            "  ↑↓/jk: select agent   enter: confirm   esc: cancel  "
889	        } else {
890	            "  type to enter   enter: next   esc: cancel  "
891	        };
892	        draw_status(stdout, bar, w, h).ok();
893	
894	        // Position terminal cursor for text input steps
895	        if step > 0 {
896	            let row = step_rows[step];
897	            let col = (LABEL_W + inputs[step - 1].len()).min(w.saturating_sub(1));
898	            execute!(stdout, cursor::MoveTo(col as u16, row as u16)).ok();
899	        }
900	        stdout.flush().ok();
901	
902	        // ── Handle input ──────────────────────────────────────────────────────
903	        match event::read().ok()? {
904	            Event::Key(k) => match k.code {
905	                KeyCode::Esc => {
906	                    execute!(stdout, cursor::Hide).ok();
907	                    return None;
908	                }
909	                KeyCode::Up   | KeyCode::Char('k') if step == 0 => {
910	                    if agent_sel > 0 { agent_sel -= 1; }
911	                }
912	                KeyCode::Down | KeyCode::Char('j') if step == 0 => {
913	                    if agent_sel + 1 < AGENTS.len() { agent_sel += 1; }
914	                }
915	                KeyCode::Backspace if step > 0 => {
916	                    inputs[step - 1].pop();
917	                }
918	                KeyCode::Char(c) if step > 0 && !k.modifiers.contains(crossterm::event::KeyModifiers::CONTROL) => {
919	                    inputs[step - 1].push(c);
920	                }
921	                KeyCode::Enter => match step {
922	                    0 => { confirmed_agent = agent_sel; step = 1; }
923	                    1 | 2 => { step += 1; }
924	                    _ => {
925	                        execute!(stdout, cursor::Hide).ok();
926	                        let (agent_name, agent_cli, _) = AGENTS[confirmed_agent];
927	                        let branch_raw = inputs[0].trim().to_string();
928	                        return Some(NewSessionConfig {
929	                            agent_name: agent_name.to_string(),
930	                            agent_cli: agent_cli.to_string(),
931	                            branch: if branch_raw.is_empty() { None } else { Some(branch_raw) },
932	                            session_name: inputs[1].trim().to_string(),
933	                            prompt: inputs[2].trim().to_string(),
934	                            repo_dir: repo_dir.to_string(),
935	                        });
936	                    }
937	                },
938	                _ => {}
939	            },
940	            _ => {}
941	        }
942	    }
943	}
944	
945	// ── Helpers ───────────────────────────────────────────────────────────────────
946	
947	fn create_worktree(repo_dir: &str, branch: &str) -> String {
948	    let repo_path = std::path::Path::new(repo_dir);
949	    let parent = match repo_path.parent() {
950	        Some(p) => p,
951	        None => return "Error: cannot determine repo parent directory".to_string(),
952	    };
953	    let repo_name = repo_path
954	        .file_name()
955	        .map(|s| s.to_string_lossy().to_string())
956	        .unwrap_or_else(|| "repo".to_string());
957	    let wt_path = parent.join(format!("{repo_name}-{branch}"));
958	
959	    // Try -b (new branch) first; fall back to checking out an existing branch.
960	    let out = std::process::Command::new("git")
961	        .args(["worktree", "add", "-b", branch, wt_path.to_str().unwrap_or("")])
962	        .current_dir(repo_dir)
963	        .output();
964	
965	    match out {
966	        Err(e) => format!("Error: {e}"),
967	        Ok(o) if o.status.success() => {
968	            format!("Created worktree: {}", short_path_s(wt_path.to_str().unwrap_or("")))
969	        }
970	        Ok(o) => {
971	            let msg = String::from_utf8_lossy(&o.stderr);
972	            let first = msg.lines().find(|l| !l.trim().is_empty()).unwrap_or("unknown error");
973	            format!("Error: {first}")
974	        }
975	    }
976	}
