989	fn user_text(content: &serde_json::Value) -> Option<String> {
990	    match content {
991	        serde_json::Value::String(s) if !s.trim().is_empty() => Some(s.trim().to_string()),
992	        serde_json::Value::Array(blocks) => {
993	            blocks.iter().find_map(|b| {
994	                if b["type"].as_str() == Some("text") {
995	                    b["text"].as_str().filter(|t| !t.trim().is_empty()).map(|t| t.trim().to_string())
996	                } else { None }
997	            })
998	        }
999	        _ => None,
1000	    }
1001	}
