1003	fn with_bg(s: &str, bg: &str) -> String {
1004	    let reinsert = format!("\x1b[0m\x1b[{bg}m");
1005	    let body = s.replace("\x1b[0m", &reinsert);
1006	    format!("\x1b[{bg}m{body}")
1007	}
