1009	fn visible_width(s: &str) -> usize {
1010	    let mut w = 0usize;
1011	    let mut chars = s.chars().peekable();
1012	    while let Some(c) = chars.next() {
1013	        if c == '\x1b' {
1014	            for nc in chars.by_ref() { if nc.is_ascii_alphabetic() { break; } }
1015	        } else {
1016	            w += 1;
1017	        }
1018	    }
1019	    w
1020	}
1021	
1022	fn relative_time(dt: DateTime<Utc>) -> String {
1023	    let secs = (Utc::now() - dt).num_seconds().max(0);
1024	    if secs < 604_800 {
1025	        match secs {
1026	            s if s < 60     => "just now".to_string(),
1027	            s if s < 3_600  => format!("{} min{} ago", s/60,     if s/60==1     {""} else {"s"}),
1028	            s if s < 86_400 => format!("{} hr{} ago",  s/3_600,  if s/3_600==1  {""} else {"s"}),
1029	            s               => format!("{} day{} ago", s/86_400, if s/86_400==1 {""} else {"s"}),
1030	        }
1031	    } else {
1032	        dt.with_timezone(&Local).format("%m/%d/%y").to_string()
1033	    }
1034	}
1035	
1036	pub fn run_for_dir(repo_dir: &str) -> Result<()> {
1037	    let conn = db::connect()?;
1038	    let repos = fetch_repos(&conn)?;
1039	    let start = repos.iter().position(|r| r.directory == repo_dir);
1040	
1041	    let orig_hook = std::panic::take_hook();
1042	    std::panic::set_hook(Box::new(move |info| {
1043	        let mut out = io::stdout();
1044	        let _ = execute!(out, LeaveAlternateScreen, cursor::Show);
1045	        let _ = terminal::disable_raw_mode();
1046	        orig_hook(info);
1047	    }));
1048	
1049	    let mut stdout = io::stdout();
1050	    terminal::enable_raw_mode()?;
1051	    execute!(stdout, EnterAlternateScreen, cursor::Hide)?;
1052	
1053	    let outcome = tui_loop(&mut stdout, &repos, false, start);
1054	
1055	    execute!(stdout, LeaveAlternateScreen, cursor::Show)?;
1056	    terminal::disable_raw_mode()?;
1057	
1058	    match outcome? {
1059	        Some(TuiOutcome::ResumeSession { id, cwd }) => {
1060	            super::show::resume_session(&id, &cwd);
1061	        }
1062	        Some(TuiOutcome::LaunchAgent { cli, cwd, session_name, prompt }) => {
1063	            use std::os::unix::process::CommandExt;
1064	            let mut cmd = std::process::Command::new(&cli);
1065	            if !cwd.is_empty() { cmd.current_dir(&cwd); }
1066	            if !session_name.is_empty() { cmd.args(["-n", &session_name]); }
1067	            if !prompt.is_empty() { cmd.arg(&prompt); }
1068	            let err = cmd.exec();
1069	            eprintln!("Failed to launch {cli}: {err}");
1070	        }
1071	        _ => {}
1072	    }
1073	
1074	    Ok(())
1075	}
1076	
1077	pub fn fetch_repos(conn: &rusqlite::Connection) -> Result<Vec<Repository>> {
1078	    let mut stmt = conn.prepare("SELECT id, directory, remote, name FROM repositories ORDER BY name")?;
1079	    let repos = stmt.query_map([], |row| {
1080	        Ok(Repository {
1081	            id: row.get(0)?,
1082	            directory: row.get(1)?,
1083	            remote: row.get(2)?,
1084	            name: row.get(3)?,
1085	        })
1086	    })?
1087	    .collect::<Result<Vec<_>, _>>()?;
1088	    Ok(repos)
1089	}
